def fx(op,n=0,target='own',**kw):return dict(op=op,n=n,target=target,**kw)
def reson(s,minimum=3,**kw):return dict(presence={s:minimum},**kw)
def add(num,name,school,typ,cost,stats,rarity,text,effects,scene,ess=(1,3),req=None,keys=(),support=False,vigil=None,flavor='',**extra):
    schools=school.split('/')
    card=dict(id=f'TDP-{num:03}',name=name,type=typ,schools=schools,cost=cost,
      presence=req or ({} if typ=='Prenúncio' else {s:1 for s in schools}),
      force=stats[0] if stats else None,vigor=stats[1] if stats else None,
      essence=dict(generation=ess[0],duration=ess[1]),support=support,vigil=vigil,
      keywords=list(keys),rarity=rarity,text=text,fx=effects,scene=scene,role=text,
      flavor=flavor or 'As passagens lembram quem aprende a atravessá-las.',**extra)
    if 'death' in effects:
        card['text']=card['text'].replace('Ao morrer,','Ao morrer durante o seu turno,')
        card['role']=card['text']
    cards.append(card)
